import{_ as e,o as i,c as r,ao as a}from"./chunks/framework.CkURMYgQ.js";const y=JSON.parse('{"title":"GEMB variables","description":"","frontmatter":{},"headers":[],"relativePath":"variables.md","filePath":"variables.md","lastUpdated":null}'),l={name:"variables.md"};function n(d,t,s,o,g,h){return i(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="GEMB-variables" tabindex="-1">GEMB variables <a class="header-anchor" href="#GEMB-variables" aria-label="Permalink to &quot;GEMB variables {#GEMB-variables}&quot;">​</a></h1><p>Below is a list of variables used by GEMB.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Variable</th><th style="text-align:right;">Units</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">age</td><td style="text-align:right;">d</td><td style="text-align:right;">Mass-weighted mean age, in decimal days, of all mass in a cell (ice/firn matrix plus pore water), measured from column initialization. Snowfall, rain and vapour deposition enter at age 0; meltwater carries the age of the firn it melted from. Accumulates across gemb_spinup cycles, so for a spun-up run the epoch is the start of spinup.</td></tr><tr><td style="text-align:right;">albedo_broadband</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Time series of broadband surface albedo (model output).</td></tr><tr><td style="text-align:right;">albedo_density_threshold</td><td style="text-align:right;">kg m&lt;sup&gt;-3&lt;/sup&gt;</td><td style="text-align:right;">Density threshold below which albedo_method is applied (Default Inf).</td></tr><tr><td style="text-align:right;">albedo_fixed</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Fixed albedo used if albedo_method=&quot;None&quot; or density &gt; threshold.</td></tr><tr><td style="text-align:right;">albedo_ice</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Albedo for bare ice (0.2-0.6).</td></tr><tr><td style="text-align:right;">albedo_method</td><td style="text-align:right;">string</td><td style="text-align:right;">Scheme: &quot;GardnerSharp&quot;, &quot;GreuellKonzelmann&quot;, etc.</td></tr><tr><td style="text-align:right;">albedo_snow</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Albedo for fresh snow (0.5-0.95).</td></tr><tr><td style="text-align:right;">aquifer_depth</td><td style="text-align:right;">m</td><td style="text-align:right;">Depth to the water table — the top of the shallowest cell holding more water than irreducible saturation — in the column saved as output at that instant. NaN when the column holds no standing water, so &quot;dry&quot; stays distinguishable from &quot;water table at the surface&quot;. NaN throughout a run at the default runoff_method &quot;instantaneous&quot;, under which no cell can exceed irreducible saturation.</td></tr><tr><td style="text-align:right;">aquifer_thickness</td><td style="text-align:right;">m</td><td style="text-align:right;">Total thickness of cells holding standing (super-irreducible) water, i.e. the saturated thickness a borehole would find wet, in the column saved as output at that instant. A cell counts as saturated once it exceeds irreducible by 1e-3 of its pore space, which excludes the negligible over-saturation left by compaction within a timestep; 0 throughout a run at the default runoff_method &quot;instantaneous&quot;.</td></tr><tr><td style="text-align:right;">black_carbon_ice</td><td style="text-align:right;">ppmw</td><td style="text-align:right;">black carbon concentration in ice (parts per million by weight).</td></tr><tr><td style="text-align:right;">black_carbon_snow</td><td style="text-align:right;">ppmw</td><td style="text-align:right;">black carbon concentration in snow (parts per million by weight).</td></tr><tr><td style="text-align:right;">blowing_snow</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Net surface mass flux from wind rework of snow, accumulated over the output interval: positive is mass gained (drift deposition), negative is mass lost (blowing-snow sublimation, drift erosion). The sum of both blowing-snow paths, so it is directly comparable with RACMO&#39;s SnowDrif and with precipitation. Zero unless blowing_snow_sublimation or a drift rate is set — the wind-slab compaction and grain fragmentation of blowing_snow_method = &quot;Crocus&quot; conserve mass and so contribute nothing to it.</td></tr><tr><td style="text-align:right;">blowing_snow_method</td><td style="text-align:right;">string</td><td style="text-align:right;">Wind rework of snow already on the ground: &quot;none&quot; (<strong>the default</strong> — no wind rework) or &quot;Crocus&quot; (the SURFEX/Crocus SNOWDRIFT scheme — a per-layer mobility and driftability index, wind-slab compaction toward 350 kg m&lt;sup&gt;-3&lt;/sup&gt;, and grain fragmentation, decaying exponentially with the overburden above each layer). The compaction path is exactly mass-conserving; only blowing_snow_sublimation moves mass across the surface.</td></tr><tr><td style="text-align:right;">blowing_snow_sublimation</td><td style="text-align:right;">logical</td><td style="text-align:right;">Whether blowing_snow_method = &quot;Crocus&quot; also sublimates the suspended fraction, after Gordon et al. (2006) as Crocus implements it (default false, matching Crocus&#39;s own default). Removes mass from the surface cell, capped at half of it per timestep, and reported in blowing_snow. The latent heat is drawn from the air the particles are suspended in, not from the pack, so no latent heat is charged to the column — unlike surface sublimation.</td></tr><tr><td style="text-align:right;">cloud_fraction</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Cloud fraction (0-1) for GreuellKonzelmann method.</td></tr><tr><td style="text-align:right;">cloud_optical_thickness</td><td style="text-align:right;">dimensionless</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;">column_dzmax</td><td style="text-align:right;">m</td><td style="text-align:right;">Maximum allowable grid spacing. See Figure 1 of <a href="https://doi.org/10.5194/gmd-16-2277-2023" target="_blank" rel="noreferrer">Gardner et al., 2023</a></td></tr><tr><td style="text-align:right;">column_dzmin</td><td style="text-align:right;">m</td><td style="text-align:right;">Minimum allowable grid spacing. See Figure 1 of <a href="https://doi.org/10.5194/gmd-16-2277-2023" target="_blank" rel="noreferrer">Gardner et al., 2023</a></td></tr><tr><td style="text-align:right;">column_dztop</td><td style="text-align:right;">m</td><td style="text-align:right;">Initial surface grid spacing. See Figure 1 of <a href="https://doi.org/10.5194/gmd-16-2277-2023" target="_blank" rel="noreferrer">Gardner et al., 2023</a></td></tr><tr><td style="text-align:right;">column_zmax</td><td style="text-align:right;">m</td><td style="text-align:right;">Maximum total column depth. See Figure 1 of <a href="https://doi.org/10.5194/gmd-16-2277-2023" target="_blank" rel="noreferrer">Gardner et al., 2023</a></td></tr><tr><td style="text-align:right;">column_zmin</td><td style="text-align:right;">m</td><td style="text-align:right;">Minimum total column depth. See Figure 1 of <a href="https://doi.org/10.5194/gmd-16-2277-2023" target="_blank" rel="noreferrer">Gardner et al., 2023</a></td></tr><tr><td style="text-align:right;">column_ztop</td><td style="text-align:right;">m</td><td style="text-align:right;">Depth of constant grid spacing at the surface. See Figure 1 of <a href="https://doi.org/10.5194/gmd-16-2277-2023" target="_blank" rel="noreferrer">Gardner et al., 2023</a>.</td></tr><tr><td style="text-align:right;">column_zy</td><td style="text-align:right;">m</td><td style="text-align:right;">Grid stretching factor for lower layers. See Figure 1 of <a href="https://doi.org/10.5194/gmd-16-2277-2023" target="_blank" rel="noreferrer">Gardner et al., 2023</a></td></tr><tr><td style="text-align:right;">densification_coeffs_M01</td><td style="text-align:right;">string</td><td style="text-align:right;">Coefficients for Ligtenberg model (e.g., &quot;Gre_RACMO_GS_SW0&quot;).</td></tr><tr><td style="text-align:right;">densification_from_compaction</td><td style="text-align:right;">m</td><td style="text-align:right;">Compaction due to densification.</td></tr><tr><td style="text-align:right;">densification_from_melt</td><td style="text-align:right;">m</td><td style="text-align:right;">Compaction due to melt.</td></tr><tr><td style="text-align:right;">densification_method</td><td style="text-align:right;">string</td><td style="text-align:right;">Model: &quot;HerronLangway&quot;, &quot;Arthern&quot;, &quot;ArthernB&quot;, &quot;Barnola1991&quot;, &quot;Crocus&quot;, &quot;CrocusPure&quot;, &quot;GSFC2020&quot;, &quot;Simonsen2013&quot;, &quot;Ligtenberg&quot;.</td></tr><tr><td style="text-align:right;">density</td><td style="text-align:right;">kg m&lt;sup&gt;-3&lt;/sup&gt;</td><td style="text-align:right;">Column density.</td></tr><tr><td style="text-align:right;">density_ice</td><td style="text-align:right;">kg m&lt;sup&gt;-3&lt;/sup&gt;</td><td style="text-align:right;">Density of pure glacier ice (default 917, matching the Community Firn Model and IMAU-FDM).</td></tr><tr><td style="text-align:right;">drift_rate</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt; yr&lt;sup&gt;-1&lt;/sup&gt;</td><td style="text-align:right;">Prescribed net drifting-snow divergence, positive for erosion and negative for deposition (default 0, which disables the term). A constant-rate shorthand for the snow_drift forcing layer, used only when the forcing carries no drift; a nonzero snow_drift layer always takes precedence. Bounded to ±2000.</td></tr><tr><td style="text-align:right;">dz</td><td style="text-align:right;">m</td><td style="text-align:right;">Layer thickness profile.</td></tr><tr><td style="text-align:right;">elevation</td><td style="text-align:right;">m</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;">emissivity</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Base longwave emissivity in the range of 0 to 1.</td></tr><tr><td style="text-align:right;">emissivity_grain_radius_large</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Emissivity for large grain sizes, in the range of 0 to 1.</td></tr><tr><td style="text-align:right;">emissivity_grain_radius_threshold</td><td style="text-align:right;">mm</td><td style="text-align:right;">Grain radius threshold for emissivity switching.</td></tr><tr><td style="text-align:right;">emissivity_method</td><td style="text-align:right;">string</td><td style="text-align:right;">Method: &quot;uniform&quot;, &quot;grain_radius_threshold&quot;, &quot;grain_radius_w_threshold&quot;.</td></tr><tr><td style="text-align:right;">evaporation_condensation</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Net vapour mass exchange, accumulated over the output interval: positive is mass gained by the column (condensation/deposition), negative is mass lost (evaporation/sublimation).</td></tr><tr><td style="text-align:right;">firn_air_content</td><td style="text-align:right;">m</td><td style="text-align:right;">Total height of all air in the firn column.</td></tr><tr><td style="text-align:right;">firn_air_content_10m</td><td style="text-align:right;">m</td><td style="text-align:right;">Height of air in the top 10 m of the column, the depth-limited form the firn-core literature reports. The cell straddling 10 m contributes in proportion.</td></tr><tr><td style="text-align:right;">firn_air_content_20m</td><td style="text-align:right;">m</td><td style="text-align:right;">Height of air in the top 20 m of the column.</td></tr><tr><td style="text-align:right;">grain_dendricity</td><td style="text-align:right;">fraction</td><td style="text-align:right;">grain dendricity in the range of 0 to 1.</td></tr><tr><td style="text-align:right;">grain_growth_method</td><td style="text-align:right;">string</td><td style="text-align:right;">Dry non-dendritic grain growth: &quot;Arthern&quot; (Arthern et al., 2010 — <strong>the default</strong>, as shipped by the Community Firn Model; grows at every density), &quot;Marbouty&quot; (Marbouty, 1980 — temperature-gradient driven, but stops dead above 400 kg m&lt;sup&gt;-3&lt;/sup&gt;), or &quot;hybrid&quot; (Marbouty below that ceiling, Arthern at and above it). Wet cells take the Brun branch on every setting.</td></tr><tr><td style="text-align:right;">grain_radius</td><td style="text-align:right;">mm</td><td style="text-align:right;">Effective grain radius.</td></tr><tr><td style="text-align:right;">grain_sphericity</td><td style="text-align:right;">fraction</td><td style="text-align:right;">grain sphericity in the range of 0 to 1.</td></tr><tr><td style="text-align:right;">heat_flux_latent</td><td style="text-align:right;">W m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Latent heat flux (positive toward surface).</td></tr><tr><td style="text-align:right;">heat_flux_sensible</td><td style="text-align:right;">W m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Sensible heat flux (positive toward surface).</td></tr><tr><td style="text-align:right;">horizontal_strain_rate</td><td style="text-align:right;">yr&lt;sup&gt;-1&lt;/sup&gt;</td><td style="text-align:right;">Horizontal strain rate, the trace of the horizontal strain-rate tensor (ε̇&lt;sub&gt;xx&lt;/sub&gt; + ε̇&lt;sub&gt;yy&lt;/sub&gt;). Positive is divergence, which thins every layer at constant density; negative is convergence. Default 0, which disables the term.</td></tr><tr><td style="text-align:right;">ice_slab_depth</td><td style="text-align:right;">m</td><td style="text-align:right;">Depth to the top of the shallowest flow-blocking ice slab, in the column saved as output at that instant. NaN when no slab qualifies, so &quot;no slab&quot; stays distinguishable from &quot;slab at the surface&quot;.</td></tr><tr><td style="text-align:right;">ice_slab_thickness</td><td style="text-align:right;">m</td><td style="text-align:right;">Total thickness of cells at or above impermeable_density, whether or not they block flow, in the column saved as output at that instant.</td></tr><tr><td style="text-align:right;">impermeable_density</td><td style="text-align:right;">kg m&lt;sup&gt;-3&lt;/sup&gt;</td><td style="text-align:right;">Density at or above which a cell&#39;s pore space is treated as disconnected, so percolating water cannot pass a sufficiently thick run of such cells (default 830). Across the RetMIP models this criterion spans 810 to 917.</td></tr><tr><td style="text-align:right;">impermeable_thickness</td><td style="text-align:right;">m</td><td style="text-align:right;">Minimum contiguous thickness of cells at or above impermeable_density for the run to block percolation and route water to runoff (default 0.1). Below this, water passes through: thin lenses are laterally discontinuous at the scale the model represents.</td></tr><tr><td style="text-align:right;">latent_heat</td><td style="text-align:right;">J kg&lt;sup&gt;-1&lt;/sup&gt;</td><td style="text-align:right;">Latent heat of vaporization or sublimation used.</td></tr><tr><td style="text-align:right;">latitude</td><td style="text-align:right;">degrees</td><td style="text-align:right;">Geographic coordinate in decimal degrees.</td></tr><tr><td style="text-align:right;">longitude</td><td style="text-align:right;">degrees</td><td style="text-align:right;">Geographic coordinate in decimal degrees.</td></tr><tr><td style="text-align:right;">longwave_downward</td><td style="text-align:right;">W m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Downward longwave radiation.</td></tr><tr><td style="text-align:right;">longwave_net</td><td style="text-align:right;">W m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Net longwave radiation.</td></tr><tr><td style="text-align:right;">mass_added</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Mass added (positive) or removed (negative) by manage_layers.</td></tr><tr><td style="text-align:right;">melt</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Melt mass</td></tr><tr><td style="text-align:right;">melt_geometry</td><td style="text-align:right;">string</td><td style="text-align:right;">What melting does to a cell&#39;s geometry: &quot;thickness&quot; (<strong>the default</strong> — density held fixed and dz shrinks, as in Crocus) or &quot;density&quot; (dz held fixed and density falls, as in SNOWPACK). Refreezing is at constant thickness either way, so only &quot;density&quot; makes a melt–refreeze cycle return the cell&#39;s geometry along with its mass. Fourteau et al. (2026) Sect. 2.3 argues for &quot;density&quot;: the phase change occurs within the microstructure, and the high density of wet snow is better explained by its low viscosity under overburden than by melt-driven thinning.</td></tr><tr><td style="text-align:right;">new_snow_method</td><td style="text-align:right;">string</td><td style="text-align:right;">Fresh snow density model (e.g., :Constant350, :Fausto, :Pahaut). :Pahaut is Pahaut (1975) as Crocus implements it, the one option fitted to alpine seasonal snow rather than to a polar ice sheet — prefer it for temperate and mid-latitude glaciers.</td></tr><tr><td style="text-align:right;">output_frequency</td><td style="text-align:right;">string</td><td style="text-align:right;">Output resolution: &quot;daily&quot;, &quot;monthly&quot;, &quot;all&quot;, or &quot;last&quot;.</td></tr><tr><td style="text-align:right;">output_padding</td><td style="text-align:right;">integer value</td><td style="text-align:right;">Extra vertical levels for grid resizing (default: 1000).</td></tr><tr><td style="text-align:right;">percolation_depth</td><td style="text-align:right;">m</td><td style="text-align:right;">Deepest the meltwater wetting front reached during the output interval (an interval maximum, not a mean). Comparable to upward-looking-radar estimates. Zero when no water moved.</td></tr><tr><td style="text-align:right;">precipitation</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt; or mmwe</td><td style="text-align:right;">Mass of precipitation that falls within each time step.</td></tr><tr><td style="text-align:right;">pore_saturation_max</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Cap on how full a cell may get when water ponds above a barrier, as a fraction of its pore space (default 1.0, i.e. full saturation permitted). Capacity is (density_ice − density)·pore_saturation_max·dz, the same form irreducible retention uses, so water/capacity is the saturation water_irreducible_saturation is defined against. Only read when runoff_method is not &quot;instantaneous&quot;.</td></tr><tr><td style="text-align:right;">precipitation_mean</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Climatologial mean precipitation per time step</td></tr><tr><td style="text-align:right;">pressure_air</td><td style="text-align:right;">Pa</td><td style="text-align:right;">Air pressure</td></tr><tr><td style="text-align:right;">Profile</td><td style="text-align:right;">table</td><td style="text-align:right;">Table output by <code>model_initialize_profile</code> and input into <code>gemb</code> containing nine variables that describe the initial state of the snow/firn/ice column.</td></tr><tr><td style="text-align:right;">rain</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Rain mass.</td></tr><tr><td style="text-align:right;">rain_temperature_threshold</td><td style="text-align:right;">K</td><td style="text-align:right;">Temperature threshold above which precipitation falls as rain.</td></tr><tr><td style="text-align:right;">refreeze</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Refrozen mass</td></tr><tr><td style="text-align:right;">relative_humidity</td><td style="text-align:right;">percent</td><td style="text-align:right;">Relative humidity in the range of 0 to 100 percent.</td></tr><tr><td style="text-align:right;">run_prefix</td><td style="text-align:right;">string</td><td style="text-align:right;">Unique run identifier (default: &quot;default&quot;).</td></tr><tr><td style="text-align:right;">runoff</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Runoff mass</td></tr><tr><td style="text-align:right;">runoff_method</td><td style="text-align:right;">string</td><td style="text-align:right;">How water that percolation cannot pass leaves the column: &quot;instantaneous&quot; (the default — blocked water runs off within the time step and no cell can exceed irreducible saturation), &quot;ZuoOerlemans&quot; (a slope-dependent characteristic timescale, τ = c&lt;sub&gt;1&lt;/sub&gt; + c&lt;sub&gt;2&lt;/sub&gt;·exp(−c&lt;sub&gt;3&lt;/sub&gt;·S)), or &quot;Darcy&quot; (a saturated-conductivity flux down the slope). The latter two let water pond above a barrier and drain over a finite timescale, which is what makes standing water and firn aquifers representable; both are scaled by surface_slope.</td></tr><tr><td style="text-align:right;">shortwave_absorption_method</td><td style="text-align:right;"></td><td style="text-align:right;">TO BE CHANGED</td></tr><tr><td style="text-align:right;">shortwave_downward</td><td style="text-align:right;">W m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Downward shortwave radiation.</td></tr><tr><td style="text-align:right;">shortwave_downward_diffuse</td><td style="text-align:right;">W m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Downward diffusive shortwave flux.</td></tr><tr><td style="text-align:right;">shortwave_net</td><td style="text-align:right;">W m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Net shortwave radiation.</td></tr><tr><td style="text-align:right;">snow_drift</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt; yr&lt;sup&gt;-1&lt;/sup&gt;</td><td style="text-align:right;">Optional forcing layer: net drifting-snow divergence at each timestep, positive for erosion and negative for deposition. The IMAU-FDM path — the layer a RACMO SnowDrif field is passed through. Absent from a forcing DimStack, it defaults to zeros, in which case a nonzero drift_rate is used instead. Bounded to ±2000.</td></tr><tr><td style="text-align:right;">solar_zenith_angle</td><td style="text-align:right;">degrees</td><td style="text-align:right;">Solar zenith angle.</td></tr><tr><td style="text-align:right;">strain_thinning</td><td style="text-align:right;">m</td><td style="text-align:right;">Column thickness change from horizontal ice-dynamic strain (positive is thinning). Zero unless horizontal_strain_rate is set.</td></tr><tr><td style="text-align:right;">surface_roughness_effective_ratio</td><td style="text-align:right;"></td><td style="text-align:right;">Ratio of physical surface roughness to effective roughness.</td></tr><tr><td style="text-align:right;">surface_slope</td><td style="text-align:right;">m m&lt;sup&gt;-1&lt;/sup&gt;</td><td style="text-align:right;">Surface slope, the lateral hydraulic gradient driving runoff under runoff_method &quot;ZuoOerlemans&quot; or &quot;Darcy&quot; (default 0, unread under &quot;instantaneous&quot;). A gradient, not degrees: the RetMIP sites span 0 (Summit) to 0.6 degrees (the firn-aquifer site), i.e. 0 to about 0.010 m m&lt;sup&gt;-1&lt;/sup&gt;. &quot;Darcy&quot; requires a positive value, since its flux is proportional to the slope.</td></tr><tr><td style="text-align:right;">temperature</td><td style="text-align:right;">K</td><td style="text-align:right;">Column temperature.</td></tr><tr><td style="text-align:right;">temperature_air</td><td style="text-align:right;">K</td><td style="text-align:right;">Air temperature.</td></tr><tr><td style="text-align:right;">temperature_air_mean</td><td style="text-align:right;">K</td><td style="text-align:right;">Climatologial average temperature.</td></tr><tr><td style="text-align:right;">temperature_observation_height</td><td style="text-align:right;">m</td><td style="text-align:right;">Thermometer height.</td></tr><tr><td style="text-align:right;">thermal_conductivity_method</td><td style="text-align:right;">string</td><td style="text-align:right;">Model: &quot;Calonne2019&quot; (Calonne et al., 2019 eq. 5; the default — a sigmoid blend at 450 kg m&lt;sup&gt;-3&lt;/sup&gt; between snow and firn branches, scaled by the temperature-dependent conductivity of ice, and continuous into ice), &quot;Calonne2019Air&quot; (the same equation carrying the air-conductivity ratio on its snow branch, as IMAU-FDM does), &quot;Sturm&quot; (Sturm et al., 1997), &quot;Calonne&quot; (Calonne et al., 2011 — density only), or &quot;Marchenko2019&quot; (Marchenko et al., 2019 eq. 30, floored at the Calonne 2011 value below their fitted density range). RetMIP recommends the 2019 formulations, and the Community Firn Model and IMAU-FDM both ship one.</td></tr><tr><td style="text-align:right;">thickness_cumulative</td><td style="text-align:right;">m</td><td style="text-align:right;">Profile thickness accounting for mass added and subtracted from the system.</td></tr><tr><td style="text-align:right;">time</td><td style="text-align:right;">datetime</td><td style="text-align:right;"><code>DateTime</code>-indexed times (a <code>datenum</code>-style numeric format is also accepted).</td></tr><tr><td style="text-align:right;">valid_profile_length</td><td style="text-align:right;"></td><td style="text-align:right;">Length of the vertical profile at the instant in time it was saved as output.</td></tr><tr><td style="text-align:right;">vapor_pressure</td><td style="text-align:right;">Pa</td><td style="text-align:right;">Vapor pressure.</td></tr><tr><td style="text-align:right;">water</td><td style="text-align:right;">kg m&lt;sup&gt;-2&lt;/sup&gt;</td><td style="text-align:right;">Pore water</td></tr><tr><td style="text-align:right;">water_irreducible_method</td><td style="text-align:right;">string</td><td style="text-align:right;">Irreducible water retention: &quot;ColeouLesaffre&quot; (Coléou &amp; Lesaffre, 1998 via Langen et al., 2017 eq. 4 — <strong>the default</strong>; saturation rises as porosity closes, and is zero at and above pore closeoff), or &quot;constant&quot; (a flat water_irreducible_saturation at every density). RetMIP recommends a density-dependent form.</td></tr><tr><td style="text-align:right;">water_irreducible_saturation</td><td style="text-align:right;">fraction</td><td style="text-align:right;">Irreducible water content saturation fraction (0-0.2, default 0.07). Read only when water_irreducible_method is &quot;constant&quot;.</td></tr><tr><td style="text-align:right;">wind_observation_height</td><td style="text-align:right;">m</td><td style="text-align:right;">Height above the surface where wind is measured or modeled.</td></tr><tr><td style="text-align:right;">wind_speed</td><td style="text-align:right;">m s&lt;sup&gt;-1&lt;/sup&gt;</td><td style="text-align:right;">Wind speed.</td></tr><tr><td style="text-align:right;">wind_speed_mean</td><td style="text-align:right;">m s&lt;sup&gt;-1&lt;/sup&gt;</td><td style="text-align:right;">Climatological average wind speed.</td></tr></tbody></table><h1 id="Author-Information" tabindex="-1">Author Information <a class="header-anchor" href="#Author-Information" aria-label="Permalink to &quot;Author Information {#Author-Information}&quot;">​</a></h1><p>The Glacier Energy and Mass Balance (GEMB) was created by Alex Gardner, with contributions from Nicole-Jeanne Schlegel and Chad Greene. Complete code and documentation are available at <a href="https://github.com/alex-s-gardner/GEMB" target="_blank" rel="noreferrer">https://github.com/alex-s-gardner/GEMB</a>. Please cite any use of GEMB as:</p><p>Gardner, A. S., Schlegel, N.-J., and Larour, E.: Glacier Energy and Mass Balance (GEMB): a model of firn processes for cryosphere research, Geosci. Model Dev., 16, 2277–2302, <a href="https://doi.org/10.5194/gmd-16-2277-2023" target="_blank" rel="noreferrer">https://doi.org/10.5194/gmd-16-2277-2023</a>, 2023.</p>',6)])])}const c=e(l,[["render",n]]);export{y as __pageData,c as default};
